#include <bits/stdc++.h>
using namespace std;

void mergeArrays(vector<int>& array, int left, int middle, int right) {
    int sizeLeft = middle - left + 1;
    int sizeRight = right - middle;
    vector<int> leftArr(sizeLeft), rightArr(sizeRight);
    for (int i = 0; i < sizeLeft; ++i) leftArr[i] = array[left + i];
    for (int j = 0; j < sizeRight; ++j) rightArr[j] = array[middle + 1 + j];
    int i = 0, j = 0, k = left;
    while (i < sizeLeft && j < sizeRight) {
        if (leftArr[i] <= rightArr[j]) {
            array[k++] = leftArr[i++];
        } else {
            array[k++] = rightArr[j++];
        }
    }
    while (i < sizeLeft) array[k++] = leftArr[i++];
    while (j < sizeRight) array[k++] = rightArr[j++];
}

void performMergeSort(vector<int>& array, int start, int end) {
    if (start < end) {
        int mid = start + (end - start) / 2;
        performMergeSort(array, start, mid);
        performMergeSort(array, mid + 1, end);
        mergeArrays(array, start, mid, end);
    }
}

int main() {
    int size;
    cin >> size;
    vector<int> data(size);
    for (int idx = 0; idx < size; ++idx) cin >> data[idx];
    performMergeSort(data, 0, size - 1);
    if (size == 1) {
        cout << data[0] << "\n";
    } else {
        int medianIndex = size / 2;
        cout << data[medianIndex] << "\n";
    }
    return 0;
}
